<?php require __DIR__.'/../bootstrap.php';admin_only();verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$slug=trim($_POST['slug']);if($name&&$slug){$pdo->prepare('INSERT INTO categories(name,slug) VALUES(?,?)')->execute([$name,$slug]);flash('ok','دسته اضافه شد.');}}if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_GET['delete']]);redirect('admin/categories.php');}$cats=$pdo->query('SELECT c.*,COUNT(p.id) products_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$title='دسته‌بندی‌ها';require __DIR__.'/../partials/header.php';?><h1>دسته‌بندی‌ها</h1><div class="panel"><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="field"><label>نام</label><input name="name" required></div><div class="field"><label>Slug</label><input name="slug" required></div><button class="btn">افزودن</button></form></div><div class="panel table-wrap"><table class="table"><tr><th>نام</th><th>Slug</th><th>محصولات</th><th></th></tr><?php foreach($cats as $c): ?><tr><td><?=e($c['name'])?></td><td><?=e($c['slug'])?></td><td><?=$c['products_count']?></td><td><a class="btn red small" data-confirm="حذف شود؟" href="<?=url('admin/categories.php?delete='.$c['id'])?>">حذف</a></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
